import{_ as e,o as t,c as r,ag as i}from"./chunks/framework.DTisvaUJ.js";const c=JSON.parse('{"title":"よくある質問 — インストール・音声認識・読み上げ","description":"Mutelinkのよくある質問。インストールや更新、音声認識、読み上げ、翻訳、VR操作、無料と有料機能について案内します。","frontmatter":{"title":"よくある質問 — インストール・音声認識・読み上げ","description":"Mutelinkのよくある質問。インストールや更新、音声認識、読み上げ、翻訳、VR操作、無料と有料機能について案内します。","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/help/faq"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"ja_JP"}],["meta",{"property":"og:title","content":"よくある質問 — インストール・音声認識・読み上げ | Mutelink"}],["meta",{"property":"og:description","content":"Mutelinkのよくある質問。インストールや更新、音声認識、読み上げ、翻訳、VR操作、無料と有料機能について案内します。"}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/help/faq"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"よくある質問 — インストール・音声認識・読み上げ | Mutelink"}],["meta",{"name":"twitter:description","content":"Mutelinkのよくある質問。インストールや更新、音声認識、読み上げ、翻訳、VR操作、無料と有料機能について案内します。"}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/help/faq"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/help/faq"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/help/faq"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/help/faq"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/help/faq"}]]},"headers":[],"relativePath":"help/faq.md","filePath":"help/faq.md"}'),n={name:"help/faq.md"};function o(l,a,h,s,u,p){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="q-a" tabindex="-1">Q&amp;A <a class="header-anchor" href="#q-a" aria-label="Permalink to &quot;Q&amp;A&quot;">​</a></h1><p>よくある疑問です。うまく動かないときは、<a href="/Mutelink-releases/help/troubleshooting">困ったときの対処</a>を見てください。</p><h2 id="インストール・更新" tabindex="-1">インストール・更新 <a class="header-anchor" href="#インストール・更新" aria-label="Permalink to &quot;インストール・更新&quot;">​</a></h2><h3 id="「windowsによってpcが保護されました」と出ます" tabindex="-1">「WindowsによってPCが保護されました」と出ます <a class="header-anchor" href="#「windowsによってpcが保護されました」と出ます" aria-label="Permalink to &quot;「WindowsによってPCが保護されました」と出ます&quot;">​</a></h3><p>コード署名をしていないため、表示されることがあります。「詳細情報」を押してから「実行」を押すと進めます。管理者権限は要りません。</p><h3 id="新しいバージョンが出たことは、どうやって分かりますか" tabindex="-1">新しいバージョンが出たことは、どうやって分かりますか <a class="header-anchor" href="#新しいバージョンが出たことは、どうやって分かりますか" aria-label="Permalink to &quot;新しいバージョンが出たことは、どうやって分かりますか&quot;">​</a></h3><p>アプリを起動したときに、アプリの中でお知らせします。設定 &gt; そのほか &gt; アプリについて からも確認できます。</p><h3 id="設定の説明は、どこにありますか" tabindex="-1">設定の説明は、どこにありますか <a class="header-anchor" href="#設定の説明は、どこにありますか" aria-label="Permalink to &quot;設定の説明は、どこにありますか&quot;">​</a></h3><p>設定画面の右上の「？」を押すと、各設定の説明が、その場に出ます。このサイトには、設定の一覧は載せていません。</p><h3 id="設定の項目が、少なく見えます" tabindex="-1">設定の項目が、少なく見えます <a class="header-anchor" href="#設定の項目が、少なく見えます" aria-label="Permalink to &quot;設定の項目が、少なく見えます&quot;">​</a></h3><p>設定 &gt; 使い方 で選んだ使い方に合わせて、必要な設定だけを出しています。全部見たいときは、同じページで「すべて表示」を選びます。</p><h2 id="音声認識" tabindex="-1">音声認識 <a class="header-anchor" href="#音声認識" aria-label="Permalink to &quot;音声認識&quot;">​</a></h2><h3 id="音声認識のエンジンは、どれを選べばいいですか" tabindex="-1">音声認識のエンジンは、どれを選べばいいですか <a class="header-anchor" href="#音声認識のエンジンは、どれを選べばいいですか" aria-label="Permalink to &quot;音声認識のエンジンは、どれを選べばいいですか&quot;">​</a></h3><p>日本語はParakeet 日本語 TDTかHaas-ja、英語はParakeet 英語、ほかの言語はQwen3-ASRかWhisper turboがおすすめです。くわしくは、<a href="/Mutelink-releases/compare/speech-recognition">音声認識エンジンの比較</a>を見てください。</p><h3 id="声を、pcの外に出したくありません" tabindex="-1">声を、PCの外に出したくありません <a class="header-anchor" href="#声を、pcの外に出したくありません" aria-label="Permalink to &quot;声を、PCの外に出したくありません&quot;">​</a></h3><p>このPCで動くエンジン(Parakeet、Haas-ja、Qwen3-ASR、Whisper turbo)を選ぶと、声はPCの外に出ません。クラウド(Web Speech、Google)を選ぶと、声がMicrosoftかGoogleのサーバーに送られます(<a href="/Mutelink-releases/about/privacy">プライバシー</a>)。</p><h3 id="友達の名前が、正しく認識されません" tabindex="-1">友達の名前が、正しく認識されません <a class="header-anchor" href="#友達の名前が、正しく認識されません" aria-label="Permalink to &quot;友達の名前が、正しく認識されません&quot;">​</a></h3><p>Parakeet 日本語 TDTでは、設定 &gt; 話す &gt; 言語と認識 の「単語と名前」に登録すると、その語が出やすくなります。</p><h3 id="言語の「自動」が選べません" tabindex="-1">言語の「自動」が選べません <a class="header-anchor" href="#言語の「自動」が選べません" aria-label="Permalink to &quot;言語の「自動」が選べません&quot;">​</a></h3><p>「自動」は、Qwen3-ASRかWhisper turboでだけ選べます。</p><h2 id="読み上げの声" tabindex="-1">読み上げの声 <a class="header-anchor" href="#読み上げの声" aria-label="Permalink to &quot;読み上げの声&quot;">​</a></h2><h3 id="どの声を選べばいいですか" tabindex="-1">どの声を選べばいいですか <a class="header-anchor" href="#どの声を選べばいいですか" aria-label="Permalink to &quot;どの声を選べばいいですか&quot;">​</a></h3><p>GPUを使いたくないとき、キャラクターの声で話したいときはVOICEVOX、自然な日本語で速く読ませたいときはIrodori-TTS、日本語以外でも読ませたいときはQwen3-TTSです。<a href="/Mutelink-releases/compare/voices">読み上げの声の聞き比べ</a>で、実際の音声を聞けます。</p><h3 id="gpuは必要ですか" tabindex="-1">GPUは必要ですか <a class="header-anchor" href="#gpuは必要ですか" aria-label="Permalink to &quot;GPUは必要ですか&quot;">​</a></h3><p>VOICEVOXと、チャットボックスへの送信だけなら、GPUは要りません。Irodori-TTSとQwen3-TTSには、Vulkanに対応したGPUが必要です。</p><h3 id="自分の声に似せた声で、読み上げられますか" tabindex="-1">自分の声に似せた声で、読み上げられますか <a class="header-anchor" href="#自分の声に似せた声で、読み上げられますか" aria-label="Permalink to &quot;自分の声に似せた声で、読み上げられますか&quot;">​</a></h3><p>Irodori-TTSとQwen3-TTSで、録音から声を登録できます(<a href="/Mutelink-releases/about/supporter">支援版</a>の機能です)。登録できるのは、ご自身の声か、声の持ち主から明確な同意を得た声だけです。</p><h3 id="日本語以外も、読み上げられますか" tabindex="-1">日本語以外も、読み上げられますか <a class="header-anchor" href="#日本語以外も、読み上げられますか" aria-label="Permalink to &quot;日本語以外も、読み上げられますか&quot;">​</a></h3><p>Qwen3-TTSで、英語、中国語、韓国語、ドイツ語、スペイン語、フランス語、イタリア語、ポルトガル語、ロシア語を読み上げられます。</p><h2 id="翻訳" tabindex="-1">翻訳 <a class="header-anchor" href="#翻訳" aria-label="Permalink to &quot;翻訳&quot;">​</a></h2><h3 id="翻訳は無料ですか" tabindex="-1">翻訳は無料ですか <a class="header-anchor" href="#翻訳は無料ですか" aria-label="Permalink to &quot;翻訳は無料ですか&quot;">​</a></h3><p>翻訳そのものと、訳した文のチャットボックスへの送信、聞こえた声の翻訳は、無料です。訳した文を声で読み上げるときだけ、<a href="/Mutelink-releases/about/supporter">支援版</a>が必要です。</p><h3 id="どの翻訳エンジンがいいですか" tabindex="-1">どの翻訳エンジンがいいですか <a class="header-anchor" href="#どの翻訳エンジンがいいですか" aria-label="Permalink to &quot;どの翻訳エンジンがいいですか&quot;">​</a></h3><p>言語によって違います。<a href="/Mutelink-releases/compare/translation">翻訳エンジンの比較</a>で、使う言語の訳を実際に読んで選んでください。文をPCの外に出したくないときは、PLaMoかTranslateGemmaを選びます。</p><h3 id="訳した文を、確認してから送れますか" tabindex="-1">訳した文を、確認してから送れますか <a class="header-anchor" href="#訳した文を、確認してから送れますか" aria-label="Permalink to &quot;訳した文を、確認してから送れますか&quot;">​</a></h3><p>いいえ。送る直前に翻訳して、そのまま送ります。</p><h2 id="聞こえた声" tabindex="-1">聞こえた声 <a class="header-anchor" href="#聞こえた声" aria-label="Permalink to &quot;聞こえた声&quot;">​</a></h2><h3 id="聞こえた声とは何ですか" tabindex="-1">聞こえた声とは何ですか <a class="header-anchor" href="#聞こえた声とは何ですか" aria-label="Permalink to &quot;聞こえた声とは何ですか&quot;">​</a></h3><p>VRChatの音をMutelinkが聞き取って、相手の言葉を文字で出す機能です。訳して出すこともできます。</p><h3 id="聞こえた声は、相手に見えますか" tabindex="-1">聞こえた声は、相手に見えますか <a class="header-anchor" href="#聞こえた声は、相手に見えますか" aria-label="Permalink to &quot;聞こえた声は、相手に見えますか&quot;">​</a></h3><p>メイン画面の一覧と、VRの中のパネルは、自分にだけ見えます。設定でチャットボックスにも出すようにすると(初期値はオフ)、インスタンスにいる全員に見えます。</p><h2 id="vr" tabindex="-1">VR <a class="header-anchor" href="#vr" aria-label="Permalink to &quot;VR&quot;">​</a></h2><h3 id="steamvrは必須ですか" tabindex="-1">SteamVRは必須ですか <a class="header-anchor" href="#steamvrは必須ですか" aria-label="Permalink to &quot;SteamVRは必須ですか&quot;">​</a></h3><p>いいえ。SteamVRが無くても、デスクトップで使えます。キーボードのショートカットで、送信や言語の切り替えもできます(設定 &gt; そのほか &gt; ホットキー)。</p><h3 id="steamvrと一緒に、起動できますか" tabindex="-1">SteamVRと一緒に、起動できますか <a class="header-anchor" href="#steamvrと一緒に、起動できますか" aria-label="Permalink to &quot;SteamVRと一緒に、起動できますか&quot;">​</a></h3><p>できます。設定 &gt; 見た目 &gt; VR の「SteamVRと一緒に起動・終了する」をオンにします。登録は、SteamVRにつながったときに行われるので、最初の1回は、SteamVRを起動した状態でMutelinkを起動してください。</p><h2 id="支援版・データ" tabindex="-1">支援版・データ <a class="header-anchor" href="#支援版・データ" aria-label="Permalink to &quot;支援版・データ&quot;">​</a></h2><h3 id="支援版を買わないと、使えませんか" tabindex="-1">支援版を買わないと、使えませんか <a class="header-anchor" href="#支援版を買わないと、使えませんか" aria-label="Permalink to &quot;支援版を買わないと、使えませんか&quot;">​</a></h3><p>いいえ。アプリ本体は無料で、買わなくても使えます。違いは、<a href="/Mutelink-releases/about/supporter">支援版</a>にまとめています。</p><h3 id="どんなデータが、外に送られますか" tabindex="-1">どんなデータが、外に送られますか <a class="header-anchor" href="#どんなデータが、外に送られますか" aria-label="Permalink to &quot;どんなデータが、外に送られますか&quot;">​</a></h3><p><a href="/Mutelink-releases/about/privacy">プライバシー</a>にまとめています。</p>',51)])])}const m=e(n,[["render",o]]);export{c as __pageData,m as default};
